#!/usr/bin/env python3
"""Generate src/shared/ItemIcons.luau from assets/renders/items/atlas.json (written by zr_items.pack_atlas in
Blender) and the uploaded sheets' image ids.

Usage: python3 tools/item_icons.py <image id of sheet 0> <image id of sheet 1> ...
"""
import json, pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
atlas = json.loads((ROOT / "assets/renders/items/atlas.json").read_text())
ids = sys.argv[1:]
assert len(ids) == len(atlas["sheets"]), "one image id per sheet: %s" % atlas["sheets"]
lines = [
    "--!strict",
    "-- Generated by tools/item_icons.py from assets/renders/items/atlas.json. Do not edit by hand.",
    "-- Inventory pictures: every item rendered in Blender (assets/blender_scripts/build_items_*.py, zr_items.py),",
    "-- packed %d px per grid cell into %d x %d sheets. items[id] = { sheet, x, y, w, h } (pixels in the sheet;" % (atlas["cell"], atlas["size"], atlas["size"]),
    "-- w x h = the item's grid size times the cell).",
    "return {",
    "\tcell = %d," % atlas["cell"],
    "\tsheets = { %s }," % ", ".join('"rbxassetid://%s"' % i for i in ids),
    "\titems = {",
]
for k in sorted(atlas["items"]):
    e = atlas["items"][k]
    lines.append("\t\t%s = { %d, %d, %d, %d, %d }," % (k, e["sheet"] + 1, e["x"], e["y"], e["w"], e["h"]))
lines += ["\t},", "}", ""]
(ROOT / "src/shared/ItemIcons.luau").write_text("\n".join(lines))
print("ItemIcons.luau:", len(atlas["items"]), "items,", len(ids), "sheets")
